/// `z` into a store key: the bits of `re` and `im` in binary64, of both
/// limbs of each in double-double (keys of different values never meet).
#[inline(always)]
fn push_key_bits<T: NativeFloat>(key: &mut Vec<u64>, z: &C<T>) {
    if T::FIXED_BITS == Some(106) {
        if let Some(z) = (z as &dyn std::any::Any).downcast_ref::<C<symbolica::domains::float::DoubleFloat>>() {
            let (re, im) = (z.re.into_inner(), z.im.into_inner());
            key.extend([re.hi().to_bits(), re.lo().to_bits(), im.hi().to_bits(), im.lo().to_bits()]);
            return;
        }
    }
    key.extend([z.re.to_f64().to_bits(), z.im.to_f64().to_bits()]);
}

/// A real setting of the executor (a gate, the gather scale) in a store
/// key: the bits of its binary64 value and, in double-double, of its low
/// limb (zero otherwise). A double-double gate need not be a binary64 number
/// (a direct workspace's default 1e-12 is the exact rational), so both limbs
/// are keyed.
pub(crate) fn real_key_words<T: NativeFloat>(x: &T) -> [u64; 2] {
    let low = if T::FIXED_BITS == Some(106) {
        (x as &dyn std::any::Any)
            .downcast_ref::<symbolica::domains::float::DoubleFloat>()
            .map_or(0, |x| x.into_inner().lo().to_bits())
    } else {
        0
    };
    [x.to_f64().to_bits(), low]

/// The leading `count` stored double-double coefficients into `out` (`false`:
/// fewer stored, or `T` is not double-double).
fn write_dd_values<T: NativeFloat>(out: &mut [L4<T>], count: usize, stored: &[[C<symbolica::domains::float::DoubleFloat>; 4]]) -> bool {
    if stored.len() < count || out.len() < count {
        return false;
    }
    for (slots, value) in out[..count].iter_mut().zip(stored) {
        for (slot, z) in slots.iter_mut().zip(value) {
            if !set_from_dd(slot, z) {
                return false;
            }
        }
    }
    true
}

/// Coefficients as double-double values to store (`None`: `T` is not
/// double-double).
fn read_dd_values<T: NativeFloat>(values: &[L4<T>]) -> Option<Vec<[C<symbolica::domains::float::DoubleFloat>; 4]>> {
    values
        .iter()
        .map(|slots| Some([to_dd(&slots[0])?, to_dd(&slots[1])?, to_dd(&slots[2])?, to_dd(&slots[3])?]))
        .collect()
}

/// Key of a double-double scalar master: family, arity and the limbs of
/// every argument bit for bit (`false`: `T` is not double-double).
fn dd_master_key<T: NativeFloat>(key: &mut Vec<u64>, family: usize, arity: usize, input: &[C<T>]) -> bool {
    use symbolica::domains::float::DoubleFloat;
    key.clear();
    key.extend([7, family as u64, arity as u64]);
    for z in input {
        let Some(z) = (z as &dyn std::any::Any).downcast_ref::<C<DoubleFloat>>() else { return false };
        let (re, im) = (z.re.into_inner(), z.im.into_inner());
        key.extend([re.hi().to_bits(), re.lo().to_bits(), im.hi().to_bits(), im.lo().to_bits()]);
    }
    true

pub(super) fn gram_indicator<T: NativeFloat>(z: &[[C<T>; 3]; 3], f: &[C<T>; 3], nm: usize) -> Option<f64> {
    let zero = czero(&z[0][0].re);
    let adj = |i: usize, j: usize| -> C<T> {
        if nm == 2 {
            return match (i, j) {
                (0, 0) => z[1][1].clone(),
                (1, 1) => z[0][0].clone(),
                _ => csub(&zero, &z[j][i]),
            };
        }
        let (a, b, c, d) = ((j + 1) % 3, (j + 2) % 3, (i + 1) % 3, (i + 2) % 3);
        csub(&cmul(&z[a][c], &z[b][d]), &cmul(&z[a][d], &z[b][c]))
    };
    let mut delta = zero.clone();
    for j in 0..nm {
        delta = cadd(&delta, &cmul(&z[0][j], &adj(j, 0)));
    }
    let mut largest = 0.0f64;
    for j in 0..nm {
        let mut value = zero.clone();
        for m in 0..nm {
            value = cadd(&value, &cmul(&adj(j, m), &f[m]));
        }
        largest = largest.max(cnorm2(&value).to_f64().sqrt());
    }
    let w = largest / cnorm2(&delta).to_f64().sqrt();
    (largest > 0.0 && w.is_finite()).then_some(w)

pub(super) fn cayley_cancellation<T: NativeFloat>(z: &[[C<T>; 3]; 3], f: &[C<T>; 3], m02: &C<T>, nm: usize) -> Option<f64> {
    let zero = czero(&z[0][0].re);
    let size = |x: &C<T>| cnorm2(x).to_f64().sqrt();
    let adj = |i: usize, j: usize| -> C<T> {
        if nm == 2 {
            return match (i, j) {
                (0, 0) => z[1][1].clone(),
                (1, 1) => z[0][0].clone(),
                _ => csub(&zero, &z[j][i]),
            };
        }
        let (a, b, c, d) = ((j + 1) % 3, (j + 2) % 3, (i + 1) % 3, (i + 2) % 3);
        csub(&cmul(&z[a][c], &z[b][d]), &cmul(&z[a][d], &z[b][c]))
    };
    let mut delta = zero.clone();
    for j in 0..nm {
        delta = cadd(&delta, &cmul(&z[0][j], &adj(j, 0)));
    }
    let two = z[0][0].re.from_usize(2);
    let mut det_x = cmul(&cscale(m02, &two), &delta);
    let mut terms = size(&det_x);
    for a in 0..nm {
        for b in 0..nm {
            let term = cmul(&cmul(&f[a], &f[b]), &adj(a, b));
            terms += size(&term);
            det_x = csub(&det_x, &term);
        }
    }
    let ratio = terms / size(&det_x);
    ratio.is_finite().then_some(ratio)

pub(super) fn gram_factors<T: NativeFloat>(z: &[[C<T>; 3]; 3], f: &[C<T>; 3], m02: &C<T>, nm: usize) -> Option<(f64, f64)> {
    let zero = czero(&z[0][0].re);
    let size = |x: &C<T>| cnorm2(x).to_f64().sqrt();
    let adj = |i: usize, j: usize| -> C<T> {
        if nm == 2 {
            return match (i, j) {
                (0, 0) => z[1][1].clone(),
                (1, 1) => z[0][0].clone(),
                _ => csub(&zero, &z[j][i]),
            };
        }
        let (a, b, c, d) = ((j + 1) % 3, (j + 2) % 3, (i + 1) % 3, (i + 2) % 3);
        csub(&cmul(&z[a][c], &z[b][d]), &cmul(&z[a][d], &z[b][c]))
    };
    let mut delta = zero.clone();
    for j in 0..nm {
        delta = cadd(&delta, &cmul(&z[0][j], &adj(j, 0)));
    }
    let mut largest = 0.0f64;
    for j in 0..nm {
        let mut value = zero.clone();
        for m in 0..nm {
            value = cadd(&value, &cmul(&adj(j, m), &f[m]));
        }
        largest = largest.max(size(&value));
    }
    let two = z[0][0].re.from_usize(2);
    let mut xtilde = 0.0f64;
    for a in 0..nm {
        for b in 0..nm {
            let mut value = cscale(&cmul(m02, &adj(a, b)), &two);
            for n1 in 0..nm {
                for m1 in 0..nm {
                    if let Some(w) = second_adjugate(z, nm, a, n1, b, m1) {
                        value = cadd(&value, &cmul(&w, &cmul(&f[n1], &f[m1])));
                    }
                }
            }
            xtilde = xtilde.max(size(&value));
        }
    }
    let max_z = (0..nm).flat_map(|i| (0..nm).map(move |j| (i, j))).map(|(i, j)| size(&z[i][j])).fold(0.0f64, f64::max);
    let max_f = (0..nm).map(|i| size(&f[i])).fold(0.0f64, f64::max);
    let fac_g = size(&delta) / largest * (xtilde / (2.0 * largest)).max(1.0);
    let fac_gy = largest.max(size(&delta)) / xtilde * (max_f / max_z).max(1.0);
    (largest > 0.0 && fac_g.is_finite() && fac_gy.is_finite()).then_some((fac_g, fac_gy))

//! **What is shared, and when it hits.** Every entry is a pure function of
//! its exact key, so values are bit-identical with the store attached or
//! not, whatever the order of the calls and the number of threads sharing
//! it (the store is `Send + Sync`; concurrent workspaces may compute the same
//! entry twice, never a different one):
//!
//! - binary64 scalar masters (tadpole, bubble, triangle, box), keyed by the
//!   family and the bits of their arguments: the invariants (supplied or
//!   formed from the shifts), the squared masses and mu^2. The key holds no
//!   shift, so it is translation-invariant: with supplied invariants
//!   ([`crate::InvariantInput::SuppliedInvariants`]) a box meets its copy in
//!   any loop-momentum frame, whenever its invariants are supplied bit for
//!   bit and its propagators come in the same order;
//! - binary64 PV sub-integrals and Gram-free pentagons, partial rescues and
//!   small-Gram expansions of boxes and triangles, keyed by what was
//!   computed (the method's settings, the subset's plan signature, rank and
//!   value count) and the subset's propagators bit for bit (shifts, masses,
//!   supplied invariants) with mu^2;
//! - gathered binary64 Cartesian moments of the subsets of a size and rank
//!   that some attached plan gathers inside a larger integral (a hexagon's
//!   pentagons, for instance), keyed by everything the gather reads,
//!   including the subset's origin;
//! - double-double scalar masters (double-double workspaces, partial rescues
//!   and tiers), keyed limb for limb.
//!
//! The sub-integral and moment keys hold the subset's shifts, so parent and
//! pinched families meet when the caller hands them over in one **aligned**
//! loop-momentum frame: a propagator shared by two families has the same
//! shift bit for bit in both, and the families list their common propagators
//! in the same relative order (a subset's first propagator is its PV
//! origin). Keys on differences of shifts would not do better in binary64:
//! `(p_i + a) - (p_j + a)` rounds differently from `p_i - p_j`, so two frames
//! related by a translation rarely give equal difference bits, and the
//! Cartesian moments themselves depend on the origin. In other frames
//! nothing false is ever shared: their keys simply differ.
//!
//! **Use.** [`TensorStore::register`] every plan that will be reduced with
//! the store (every (N, R) bucket) before the first call, then per chunk of
//! phase-space points: reduce, and [`TensorStore::clear`] when the points
//! change (registrations and rank floors survive it). Moments are shared
//! for the subset sizes and ranks some registered or attached plan gathers
//! inside a larger integral; without registering first, which moments meet
//! depends on the order in which workspaces attach (a hexagon's pentagon
//! moments are reused by a later pentagon call, not by an earlier one).
//! Values never depend on it.
//!
//! **Lifetime and memory.** Nothing is removed until [`TensorStore::clear`].
//! [`TensorStoreOptions::byte_budget`] (none by default: the caller's clears
//! bound the store) stops inserting entries once their estimated size
//! reaches it; a result not inserted is computed again where it is needed,
//! never changed.
//!
//! **Rank alignment (optional).** Integrals need a box or triangle at
//! different coefficient ranks; sub-integral keys include the rank, so by
//! default only equal ranks meet and every workspace computes exactly what
//! it computes alone. [`TensorStore::align_ranks`] raises the store's rank
//! floor for the injected (partially rescued or expanded) boxes and
//! triangles to a plan's ranks, as an `AmplitudeWorkspace` does for its
//! integrals: more of them meet, and every attached workspace's injected
//! boxes and triangles are then computed at the floor (results differ from a
//! workspace without the store at the expansions' truncation level, and stay
//! bit-identical with sharing on and off).
//!
//! **Masters provider (optional).** A [`MasterProvider`] given in
//! [`TensorStoreOptions::masters`] supplies the binary64 scalar masters of
//! every attached binary64 workspace (and of their binary64 auxiliary
//! executors) on a miss of the store's own master maps, before TIRust's
//! kernels: an embedder can serve them from its own cache. Its values are
//! used as returned (results change only if they differ from TIRust's
//! kernels); declining a master (`None`) leaves it to TIRust's kernels.
//! The mass derivatives of dotted propagators (IBP jets), workspaces with
//! batched [`crate::MasterExecutionPolicy`] evaluators and double-double or
//! MPFR workspaces never consult it; nothing signals that beyond
//! [`TensorStoreStatistics::masters_provided`] (an embedder crediting its
//! cache checks that count).

/// Convert internal OneLOop-normalized raw components to the selected API
/// convention. Input and output retain `[UV1, IR1, IR2, finite]` ordering.
pub(crate) fn convert_convention(
    value: &[Atom; 4],
    monomial: Monomial,
    settings: &ReductionSettings,
) -> [Atom; 4] {
    let mut result = match settings.convention {
        Convention::OneLoop => value.clone(),
        Convention::MadLoop => {
            let sign = Atom::num(if monomial.rank() % 2 == 0 { 1 } else { -1 });
            value.each_ref().map(|coefficient| coefficient * &sign)
        }
        Convention::IregiNative => {
            let pi = Atom::var(Symbol::PI);
            let a = Atom::from(symbolica::transcendental::euler_gamma()) + Symbol::LOG.call((&pi,));
            let b = pi.pow(2) / Atom::num(12);
            let replacements: Vec<_> = NATIVE_MAP
                .values
                .iter()
                .zip(value)
                .map(|(symbol, value)| Replacement::new(symbol.clone(), value.clone()))
                .chain([
                    Replacement::new(NATIVE_MAP.a.clone(), a),
                    Replacement::new(NATIVE_MAP.b.clone(), b),
                ])
                .collect();
            let normalization =
                symbolica::parse!("𝑖") * pi.pow(2 + i64::from(settings.dimension_shift));
            NATIVE_MAP
                .expressions
                .each_ref()
                .map(|expression| expression.replace_multiple(replacements.iter()) * &normalization)
        }
    };
    if settings.tensor_weights == TensorWeights::Multinomial {
        let weight = multinomial(monomial);
        for coefficient in &mut result {
            *coefficient = &*coefficient * &weight;
        }
    }
    result

